args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?director ?directorLabel ?birthplace ?birthplaceLabel WHERE {
  { dbr:Bollywood_Calling dbo:director ?director } UNION { dbr:Bollywood_Calling dbp:director ?director } .
  ?director dbo:birthPlace ?birthplace .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = "en") }
  OPTIONAL { ?birthplace rdfs:label ?birthplaceLabel FILTER (lang(?birthplaceLabel) = "en") }
}

